import { stableLabel } from './logic'

@ComponentV2
export struct StableCounter {
  @Local count: number = 0;

  @Builder
  heading() {
    Text(stableLabel(this.count)).fontSize(20)
  }

  build() {
    Column() {
      this.heading()
      Text(stableLabel(this.count))
    }.width('100%')
  }
}

